-- =====================================================================
-- Bases de Dados 2026/27 – Projeto BANDyApp – Etapa E3
-- Script base fornecido pelos docentes: esquema (6 tabelas) e dados de teste.
-- Executar numa base de dados PostgreSQL vazia (pode ser executado repetidamente).
-- Dados fictícios.
-- =====================================================================



SET search_path TO tabelase3;

DROP TABLE IF EXISTS bilhete, concerto, artista, dia, edicao, festival CASCADE;

CREATE TABLE festival (
    nome          VARCHAR(80)  NOT NULL,
    ano_criacao   NUMERIC(4)   NOT NULL,
    CONSTRAINT pk_festival PRIMARY KEY (nome),
    CONSTRAINT ck_festival_ano CHECK (ano_criacao BETWEEN 1950 AND 2100)
);

-- Edição: fraca de Festival. O recinto (nome e cidade) e a capacidade passam a colunas.
CREATE TABLE edicao (
    festival        VARCHAR(80)   NOT NULL,
    ano             NUMERIC(4)    NOT NULL,
    recinto         VARCHAR(80)   NOT NULL,
    cidade          VARCHAR(60)   NOT NULL,
    capacidade_max  INTEGER       NOT NULL,
    preco_passe     NUMERIC(7,2)  NOT NULL,
    CONSTRAINT pk_edicao PRIMARY KEY (festival, ano),
    CONSTRAINT fk_edicao_festival FOREIGN KEY (festival) REFERENCES festival (nome)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT ck_edicao_capacidade CHECK (capacidade_max > 0),   -- RIA-12
    CONSTRAINT ck_edicao_preco CHECK (preco_passe > 0)            -- RIA-12
);

-- Dia: fraca de Edição.
CREATE TABLE dia (
    festival      VARCHAR(80)   NOT NULL,
    ano           NUMERIC(4)    NOT NULL,
    data          DATE          NOT NULL,
    preco_diario  NUMERIC(7,2)  NOT NULL,
    CONSTRAINT pk_dia PRIMARY KEY (festival, ano, data),
    CONSTRAINT fk_dia_edicao FOREIGN KEY (festival, ano) REFERENCES edicao (festival, ano)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT ck_dia_ano CHECK (EXTRACT(YEAR FROM data) = ano),  -- RIA-1
    CONSTRAINT ck_dia_preco CHECK (preco_diario > 0)              -- RIA-12
);

CREATE TABLE artista (
    nome            VARCHAR(80)  NOT NULL,
    genero_musical  VARCHAR(30)  NOT NULL,
    tipo            VARCHAR(10)  NOT NULL,
    CONSTRAINT pk_artista PRIMARY KEY (nome),
    CONSTRAINT ck_artista_tipo CHECK (tipo IN ('artista', 'grupo'))  -- RIA-3
);

CREATE TABLE concerto (
    id_concerto  INTEGER GENERATED ALWAYS AS IDENTITY,   -- campo serial (valor gerado automaticamente)
    festival     VARCHAR(80)  NOT NULL,
    ano          NUMERIC(4)   NOT NULL,
    data         DATE         NOT NULL,
    artista      VARCHAR(80)  NOT NULL,
    hora_inicio  TIME         NOT NULL,
    hora_fim     TIME         NOT NULL,
    CONSTRAINT pk_concerto PRIMARY KEY (id_concerto),
    CONSTRAINT fk_concerto_dia FOREIGN KEY (festival, ano, data) REFERENCES dia (festival, ano, data)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_concerto_artista FOREIGN KEY (artista) REFERENCES artista (nome)
        ON DELETE NO ACTION ON UPDATE CASCADE,
    CONSTRAINT ck_concerto_horas CHECK (hora_inicio < hora_fim)   -- RIA-2
);

-- Bilhete: a generalização (passe geral / bilhete diário) numa única tabela, com a coluna tipo.
-- O comprador e o titular são identificados pelo email (não há tabela de utilizadores na E3).
-- O preço pago é derivado (não é guardado).
CREATE TABLE bilhete (
    id_bilhete   INTEGER GENERATED ALWAYS AS IDENTITY,   -- campo serial (valor gerado automaticamente)
    comprador    VARCHAR(254)  NOT NULL,
    titular      VARCHAR(254)  NOT NULL,
    data_compra  DATE          NOT NULL,
    tipo         VARCHAR(6)    NOT NULL,
    festival     VARCHAR(80)   NOT NULL,
    ano          NUMERIC(4)    NOT NULL,
    data         DATE,
    CONSTRAINT pk_bilhete PRIMARY KEY (id_bilhete),
    CONSTRAINT fk_bilhete_edicao FOREIGN KEY (festival, ano) REFERENCES edicao (festival, ano)
        ON DELETE NO ACTION ON UPDATE CASCADE,
    CONSTRAINT fk_bilhete_dia FOREIGN KEY (festival, ano, data) REFERENCES dia (festival, ano, data)
        ON DELETE NO ACTION ON UPDATE CASCADE,
    CONSTRAINT ck_bilhete_tipo CHECK ((tipo = 'geral' AND data IS NULL) OR (tipo = 'diario' AND data IS NOT NULL))
);

